// Letzte offene Fragen:
//  1. Wirken eckige Klammern ohne den Parameter order?
//  2. Laesst sich die Sortierung umkehren?
// Angezeigt werden Zeitstempel und Kurzform der ersten Kennung zum Vergleich.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';

function auswerten(body) {
  const roh = body?.data;
  const liste = roh && typeof roh === 'object' && !Array.isArray(roh) ? Object.entries(roh) : [];
  const eintraege = liste.map(([k, v]) => (v && typeof v === 'object' ? v : { id: k }));
  const l = body?.limit ?? {};
  const erste = eintraege[0] ?? {};
  const letzte = eintraege[eintraege.length - 1] ?? {};
  return {
    anzahl: liste.length,
    gemeldet_start: l.start ?? '-',
    gemeldet_reply: l.reply ?? '-',
    gemeldet_total: l.total ?? '-',
    erste_id: erste.id ?? null,
    erste_zeit: erste.time ?? '-',
    letzte_zeit: letzte.time ?? '-',
  };
}

async function abruf(bezeichnung, qs) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: 'GET',
      url: basis,
      headers,
      qs,
      json: true,
      returnFullResponse: true,
      timeout: 60000,
    });
    return { variante: bezeichnung, status: antwort.statusCode, ...auswerten(antwort.body) };
  } catch (fehler) {
    return {
      variante: bezeichnung,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      anzahl: 0,
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 160),
    };
  }
}

const hole = abruf.bind(this);

const varianten = [
  ['A Vergleich', { limit: 5 }],
  ['B limit Klammer start', { 'limit[start]': 100 }],
  ['C limit Klammer beides', { 'limit[start]': 100, 'limit[reply]': 5 }],
  ['D limit Klammer nur reply', { 'limit[reply]': 5 }],
  ['E order Klammer ASC', { limit: 5, 'order[time]': 'ASC' }],
  ['F order flach ASC', { limit: 5, order: 'ASC' }],
  ['G order time ASC', { limit: 5, order: 'time', direction: 'ASC' }],
  ['H sort und dir', { limit: 5, sort: 'time', dir: 'asc' }],
  ['I order Punkt ASC', { limit: 5, 'order.time': 'ASC' }],
  ['J order Pfeil ASC', { limit: 5, 'order>time': 'ASC' }],
  ['K desc aus', { limit: 5, desc: 0 }],
  ['L Hoechstwert pruefen', { limit: 4038 }],
];

const ergebnisse = [];
for (const [bezeichnung, qs] of varianten) {
  ergebnisse.push(await hole(bezeichnung, qs));
}

const vergleich = ergebnisse[0];

return ergebnisse.map((e) => ({
  json: {
    schritt: 'S10',
    variante: e.variante,
    status: e.status,
    anzahl: e.anzahl,
    gemeldet_start: e.gemeldet_start ?? '-',
    gemeldet_reply: e.gemeldet_reply ?? '-',
    andere_erste_buchung:
      e.erste_id && vergleich?.erste_id ? (e.erste_id !== vergleich.erste_id ? 'JA' : 'nein') : '-',
    erste_zeit: e.erste_zeit ?? '-',
    letzte_zeit: e.letzte_zeit ?? '-',
    fehlermeldung: e.fehlermeldung ?? '-',
  },
}));
